CREATE TABLE IF NOT EXISTS roles(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,rank INTEGER NOT NULL,title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS permissions(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id INTEGER REFERENCES roles(id) ON DELETE CASCADE,permission_id INTEGER REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL COLLATE NOCASE,pass_hash TEXT NOT NULL,role_id INTEGER NOT NULL REFERENCES roles(id),is_active INTEGER NOT NULL DEFAULT 1,reset_token_hash TEXT,reset_expires INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,full_name TEXT NOT NULL,phone TEXT,lang TEXT NOT NULL DEFAULT 'ru' CHECK(lang IN('ru','uz','en')),push_consent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS territories(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,lat REAL NOT NULL,lng REAL NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS responsible_groups(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,territory_id INTEGER REFERENCES territories(id),leader_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS group_members(group_id INTEGER REFERENCES responsible_groups(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS volunteers(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,about TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS environmental_reports(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),territory_id INTEGER REFERENCES territories(id),category TEXT NOT NULL CHECK(category IN('waste','water','air','fire','tree','other')),title TEXT NOT NULL,description TEXT NOT NULL,lat REAL NOT NULL CHECK(lat BETWEEN -90 AND 90),lng REAL NOT NULL CHECK(lng BETWEEN -180 AND 180),status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','in_progress','resolved','rejected')),group_id INTEGER REFERENCES responsible_groups(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_reports_status ON environmental_reports(status,created_at);
CREATE INDEX IF NOT EXISTS ix_reports_user ON environmental_reports(user_id);
CREATE TABLE IF NOT EXISTS report_photos(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES environmental_reports(id) ON DELETE CASCADE,file TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_status_history(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES environmental_reports(id) ON DELETE CASCADE,old_status TEXT,new_status TEXT NOT NULL,changed_by INTEGER REFERENCES users(id),note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT,territory_id INTEGER REFERENCES territories(id),starts_at TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),reward_points INTEGER NOT NULL DEFAULT 0 CHECK(reward_points>=0),created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS event_registrations(event_id INTEGER REFERENCES events(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS ecoball_wallets(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0));
CREATE TABLE IF NOT EXISTS ecoball_transactions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount<>0),kind TEXT NOT NULL,ref TEXT,idempotency_key TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_tx_user ON ecoball_transactions(user_id,id);
CREATE TABLE IF NOT EXISTS partners(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,address TEXT,is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cashback_offers(id INTEGER PRIMARY KEY,partner_id INTEGER NOT NULL REFERENCES partners(id),title TEXT NOT NULL,cost_points INTEGER NOT NULL CHECK(cost_points>0),is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS redemptions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),offer_id INTEGER NOT NULL REFERENCES cashback_offers(id),points INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'issued' CHECK(status IN('issued','used')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS qr_codes(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,redemption_id INTEGER NOT NULL REFERENCES redemptions(id) ON DELETE CASCADE,used_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,text TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS news(id INTEGER PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,author_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY,name TEXT,email TEXT,message TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,user_id INTEGER,action TEXT NOT NULL,detail TEXT,ip TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
